WITH bounds AS (SELECT CAST(strftime('%s','now') AS INTEGER)/60*60-120 AS until), runs AS (SELECT slot,started_at,completed_at,job,outcome,(CAST(started_at/60 AS INTEGER)-(((CAST(started_at/60 AS INTEGER)-slot)%4320+4320)%4320))*60 AS scheduled_at FROM cron_runs), actual AS (SELECT *,LAG(started_at) OVER(ORDER BY started_at) AS previous_start FROM runs,bounds WHERE started_at>=until-172800 AND started_at<until), scheduled AS (SELECT *,LAG(scheduled_at) OVER(ORDER BY scheduled_at) AS previous_slot FROM runs,bounds WHERE scheduled_at>=until-172800 AND scheduled_at<until) SELECT json_object('queriedAt',strftime('%Y-%m-%dT%H:%M:%SZ','now'),'from',(SELECT until-172800 FROM bounds),'until',(SELECT until FROM bounds),'scheduledRuns',(SELECT COUNT(*) FROM scheduled),'successes',(SELECT COUNT(*) FROM scheduled WHERE outcome IN ('ok','idle') AND completed_at IS NOT NULL),'failures',(SELECT COUNT(*) FROM scheduled WHERE outcome NOT IN ('ok','idle') OR completed_at IS NULL),'longestInteriorStartGap',(SELECT MAX(started_at-previous_start) FROM actual),'longestInteriorScheduledGap',(SELECT MAX(scheduled_at-previous_slot) FROM scheduled),'gapsOver180',json((SELECT json_group_array(json_object('previousStart',previous_start,'startedAt',started_at,'gapSeconds',started_at-previous_start,'job',job,'outcome',outcome)) FROM actual WHERE started_at-previous_start>180)),'failedRuns',json((SELECT json_group_array(json_object('startedAt',started_at,'completedAt',completed_at,'job',job,'outcome',outcome)) FROM scheduled WHERE outcome NOT IN ('ok','idle') OR completed_at IS NULL))) AS evidence;
